   "source": [
    "# Load and visualize lowest resolution subclusters\n",
    "\n",
    "library(Seurat)\n",
    "library(qs)\n",
    "library(ggplot2)\n",
    "library(cowplot)\n",
    "\n",
    "base_path <- \"/kaggle/input/robust-bischoff-2-1-1-subcluster-upload-gd/kaggle stage/\"\n",
    "lineages <- c(\"epithelial\", \"immune\", \"stromal\")\n",
    "n_cores <- parallel::detectCores() - 1\n",
    "\n",
    "plot_list <- list()\n",
    "\n",
    "for (lin in lineages) {\n",
    "    cat(paste0(\"Processing \", lin, \"...\\n\"))\n",
    "    \n",
    "    file_path <- paste0(base_path, \"bischoff_luad_\", lin, \".qs\")\n",
    "    obj <- qs::qread(file_path, nthreads = n_cores)\n",
    "    \n",
    "    # Dynamic resolution finder\n",
    "    res_cols <- grep(\"SCT_snn_res\\\\.\", colnames(obj@meta.data), value = TRUE)\n",
    "    \n",
    "    if (length(res_cols) > 0) {\n",
    "        # Grab min resolution\n",
    "        res_values <- as.numeric(gsub(\"SCT_snn_res\\\\.\", \"\", res_cols))\n",
    "        min_res_col <- res_cols[which.min(res_values)]\n",
    "        n_clusters <- length(unique(obj@meta.data[[min_res_col]]))\n",
    "        \n",
    "        p <- DimPlot(obj, \n",
    "                     reduction = \"umap\", \n",
    "                     group.by = min_res_col, \n",
    "                     label = TRUE, \n",
    "                     label.size = 4,\n",
    "                     repel = TRUE) +\n",
    "             labs(title = paste0(toupper(lin), \" (\", min_res_col, \")\"),\n",
    "                  subtitle = paste0(n_clusters, \" clusters | \", ncol(obj), \" cells\")) +\n",
    "             theme_minimal_grid() +\n",
    "             theme(legend.position = \"none\") \n",
    "        \n",
    "        plot_list[[lin]] <- p\n",
    "        \n",
    "    } else {\n",
    "        warning(paste(\"No resolution columns found for\", lin))\n",
    "    }\n",
    "    \n",
    "    rm(obj)\n",
    "    gc()\n",
    "}\n",
    "\n",
    "combined_plot <- plot_grid(plotlist = plot_list, ncol = 3)\n",
    "print(combined_plot)\n",
    "\n",
    "ggsave(\"lineage_subclusters_lowest_res.png\", \n",
    "       plot = combined_plot, \n",
    "       width = 45, \n",
    "       height = 15, \n",
    "       units = \"cm\", \n",
    "       dpi = 300)"
   ]
  },
