   "source": [
    "# Immune lineage processing\n",
    "# Merging external CellTypist calls and flagging contamination\n",
    "\n",
    "library(Seurat)\n",
    "library(qs)\n",
    "library(ggplot2)\n",
    "library(cowplot)\n",
    "library(dplyr)\n",
    "library(gridExtra)\n",
    "\n",
    "# -- Config --\n",
    "lineage <- \"immune\"\n",
    "base_path <- \"/kaggle/input/robust-bischoff-2-1-1-subcluster-upload-gd/kaggle stage/\"\n",
    "file_path <- paste0(base_path, \"bischoff_luad_\", lineage, \".qs\")\n",
    "celltypist_csv <- \"/kaggle/input/robust-bischoff-1-celltypist/celltypist_all_levels_comparison.csv\"\n",
    "n_cores <- parallel::detectCores() - 1\n",
    "\n",
    "message(\"Loading Immune object...\")\n",
    "imm <- qs::qread(file_path, nthreads = n_cores)\n",
    "\n",
    "# Load annotations\n",
    "celltypist_df <- read.csv(celltypist_csv, row.names = 1)\n",
    "\n",
    "# Sync barcodes\n",
    "imm_barcodes <- rownames(imm@meta.data)\n",
    "ct_barcodes <- rownames(celltypist_df)\n",
    "common_barcodes <- intersect(imm_barcodes, ct_barcodes)\n",
    "\n",
    "imm <- subset(imm, cells = common_barcodes)\n",
    "celltypist_df <- celltypist_df[common_barcodes, ]\n",
    "\n",
    "# Append metadata\n",
    "cols_to_add <- c(\"granular_raw\", \"granular_raw_conf\", \"granular_majority\", \n",
    "                 \"major_raw\", \"major_raw_conf\", \"major_majority\")\n",
    "for(col in cols_to_add) {\n",
    "    imm@meta.data[[col]] <- celltypist_df[[col]]\n",
    "}\n",
    "\n",
    "# Dictionary: Map CellTypist (Major) -> Bischoff Reference\n",
    "imm_mapping <- list(\n",
    "  \"Classical monocytes\"          = \"Monocytes\",\n",
    "  \"Non-classical monocytes\"      = \"Monocytes\",\n",
    "  \"Alveolar macrophages\"         = \"Alveolar Mph (Clusters 1-3)\",\n",
    "  \"Monocyte-derived Mph\"         = \"Monocyte-derived Mph (Clusters 1-5)\",\n",
    "  \"DC\"                           = \"Myeloid Dendritic cells\",\n",
    "  \"DC1\"                          = \"Myeloid Dendritic cells\",\n",
    "  \"DC2\"                          = \"Myeloid Dendritic cells\",\n",
    "  \"DC3\"                          = \"Myeloid Dendritic cells\",\n",
    "  \"Migratory DCs\"                = \"Myeloid Dendritic cells\",\n",
    "  \"Plasmacytoid DCs\"             = \"Plasmacytoid Dendritic cells\",\n",
    "  \"pDC\"                          = \"Plasmacytoid Dendritic cells\",\n",
    "  \"Tem/Effector helper T cells\"  = \"CD4+ T cells (Effector)\",\n",
    "  \"Tcm/Naive helper T cells\"     = \"CD4+ T cells (Naive/Memory)\",\n",
    "  \"Regulatory T cells\"           = \"CD4+ T cells (Regulatory)\",\n",
    "  \"Type 1 helper T cells\"        = \"CD4+ T cells (Th1)\",\n",
    "  \"Type 17 helper T cells\"       = \"CD4+ T cells (Th17)\",\n",
    "  \"Follicular helper T cells\"    = \"CD4+ T cells (TFH)\",\n",
    "  \"Tem/Trm cytotoxic T cells\"    = \"CD8+ T cells (Effector)\",\n",
    "  \"Tem/Temra cytotoxic T cells\"  = \"CD8+ T cells (Exhausted/Terminal)\",\n",
    "  \"Tcm/Naive cytotoxic T cells\"  = \"CD8+ T cells (Naive/Memory)\",\n",
    "  \"Trm cytotoxic T cells\"        = \"CD8+ T cells (Tissue-resident)\",\n",
    "  \"CD8a/a\"                       = \"CD8+ T cells\",\n",
    "  \"CD8a/b(entry)\"                = \"CD8+ T cells\",\n",
    "  \"CRTAM+ gamma-delta T cells\"   = \"Gamma-delta T cells\",\n",
    "  \"gamma-delta T cells\"          = \"Gamma-delta T cells\",\n",
    "  \"CD16+ NK cells\"               = \"NK cells (CD16+)\",\n",
    "  \"CD16- NK cells\"               = \"NK cells (CD16-)\",\n",
    "  \"Cycling NK cells\"             = \"NK cells (Proliferating)\",\n",
    "  \"Transitional NK\"              = \"NK cells (Transitional)\",\n",
    "  \"NKT cells\"                    = \"NKT cells\",\n",
    "  \"Memory B cells\"               = \"B cells (Memory)\",\n",
    "  \"Naive B cells\"                = \"B cells (Naive)\",\n",
    "  \"Follicular B cells\"           = \"B cells (Follicular)\",\n",
    "  \"Germinal center B cells\"      = \"B cells (Germinal center)\",\n",
    "  \"Age-associated B cells\"       = \"B cells (Age-associated)\",\n",
    "  \"Plasma cells\"                 = \"Plasma cells\",\n",
    "  \"Plasmablasts\"                 = \"Plasma cells (Plasmablasts)\",\n",
    "  \"Mast cells\"                   = \"Mast cells\",\n",
    "  \"ILC\"                          = \"Innate Lymphoid cells\",\n",
    "  \"ILC3\"                         = \"Innate Lymphoid cells (ILC3)\",\n",
    "  \"MAIT cells\"                   = \"MAIT cells\"\n",
    ")\n",
    "\n",
    "# Apply mapping\n",
    "imm@meta.data$major_celltype <- NA_character_\n",
    "imm@meta.data$is_contaminated <- FALSE\n",
    "\n",
    "for (i in seq_along(imm_mapping)) {\n",
    "  ct_name <- names(imm_mapping)[i]\n",
    "  ref_name <- imm_mapping[[i]]\n",
    "  imm@meta.data$major_celltype[imm@meta.data$major_raw == ct_name] <- ref_name\n",
    "}\n",
    "\n",
    "# Handle unmapped (contamination)\n",
    "contam_mask <- is.na(imm@meta.data$major_celltype)\n",
    "imm@meta.data$is_contaminated[contam_mask] <- TRUE\n",
    "imm@meta.data$major_celltype[contam_mask] <- \"**CONTAMINATION**\"\n",
    "\n",
    "if (sum(contam_mask) > 0) {\n",
    "  cat(sprintf(\"Warning: %d contaminating cells identified.\\n\", sum(contam_mask)))\n",
    "}\n",
    "\n",
    "# Resolutions to check\n",
    "res_cols <- grep(\"SCT_snn_res\\\\.\", colnames(imm@meta.data), value = TRUE)\n",
    "res_values <- as.numeric(gsub(\"SCT_snn_res\\\\.\", \"\", res_cols))\n",
    "res_cols <- res_cols[order(res_values)]\n",
    "\n",
    "# Helper: Analyze cluster dominance\n",
    "analyze_resolution <- function(seurat_obj, res_col, lineage_col = \"major_celltype\") {\n",
    "  clusters <- seurat_obj@meta.data[[res_col]]\n",
    "  lineages <- seurat_obj@meta.data[[lineage_col]]\n",
    "  \n",
    "  dominant_info <- list()\n",
    "  \n",
    "  for (cluster_id in sort(unique(as.character(clusters)))) {\n",
    "    mask <- clusters == cluster_id\n",
    "    counts <- table(lineages[mask])\n",
    "    \n",
    "    dom_lin <- names(counts)[which.max(counts)]\n",
    "    purity <- (max(counts) / sum(counts)) * 100\n",
    "    \n",
    "    dominant_info[[cluster_id]] <- list(\n",
    "      dominant = dom_lin,\n",
    "      purity = purity,\n",
    "      n_cells = sum(mask),\n",
    "      n_types = length(counts)\n",
    "    )\n",
    "  }\n",
    "  return(dominant_info)\n",
    "}\n",
    "\n",
    "# Plot generation loop\n",
    "plot_dir <- \"immune_resolution_plots\"\n",
    "dir.create(plot_dir, showWarnings = FALSE)\n",
    "\n",
    "# Manual palette for consistency\n",
    "imm_colors <- c(\n",
    "  \"Monocytes\" = \"#e41a1c\",\n",
    "  \"Alveolar Mph (Clusters 1-3)\" = \"#ff7f00\",\n",
    "  \"Monocyte-derived Mph (Clusters 1-5)\" = \"#ffb366\",\n",
    "  \"Myeloid Dendritic cells\" = \"#984ea3\",\n",
    "  \"Plasmacytoid Dendritic cells\" = \"#d580ff\",\n",
    "  \"CD4+ T cells (Naive/Memory)\" = \"#1b9e77\",\n",
    "  \"CD4+ T cells (Effector)\" = \"#d95f02\",\n",
    "  \"CD4+ T cells (Regulatory)\" = \"#7fc97f\",\n",
    "  \"CD4+ T cells (Th1)\" = \"#1a9850\",\n",
    "  \"CD4+ T cells (Th17)\" = \"#ffd700\",\n",
    "  \"CD4+ T cells (TFH)\" = \"#66c2a5\",\n",
    "  \"CD8+ T cells (Naive/Memory)\" = \"#377eb8\",\n",
    "  \"CD8+ T cells (Effector)\" = \"#0072b2\",\n",
    "  \"CD8+ T cells (Exhausted/Terminal)\" = \"#0070a0\",\n",
    "  \"CD8+ T cells (Tissue-resident)\" = \"#4eb3d3\",\n",
    "  \"CD8+ T cells\" = \"#2166ac\",\n",
    "  \"Gamma-delta T cells\" = \"#b3b3b3\",\n",
    "  \"NK cells (CD16+)\" = \"#fc8d62\",\n",
    "  \"NK cells (CD16-)\" = \"#fdb462\",\n",
    "  \"NK cells (Proliferating)\" = \"#fd8d3c\",\n",
    "  \"NK cells (Transitional)\" = \"#ffe07f\",\n",
    "  \"NKT cells\" = \"#fb8072\",\n",
    "  \"B cells (Naive)\" = \"#a6d96a\",\n",
    "  \"B cells (Memory)\" = \"#1a9850\",\n",
    "  \"B cells (Follicular)\" = \"#91bfdb\",\n",
    "  \"B cells (Germinal center)\" = \"#4575b4\",\n",
    "  \"B cells (Age-associated)\" = \"#abd9e9\",\n",
    "  \"Plasma cells\" = \"#9e0142\",\n",
    "  \"Plasma cells (Plasmablasts)\" = \"#d73027\",\n",
    "  \"Mast cells\" = \"#fee090\",\n",
    "  \"Innate Lymphoid cells\" = \"#e0e0e0\",\n",
    "  \"Innate Lymphoid cells (ILC3)\" = \"#bdbdbd\",\n",
    "  \"MAIT cells\" = \"#969696\",\n",
    "  \"**CONTAMINATION**\" = \"#FF0000\"\n",
    ")\n",
    "\n",
    "for (res_col in res_cols) {\n",
    "  # Stats\n",
    "  dominant_info <- analyze_resolution(imm, res_col, \"major_celltype\")\n",
    "  \n",
    "  # Impurity flag (<90% dominance)\n",
    "  imm@meta.data$impure <- FALSE\n",
    "  for (cluster_id in names(dominant_info)) {\n",
    "    if (dominant_info[[cluster_id]]$purity < 90) {\n",
    "      imm@meta.data$impure[imm@meta.data[[res_col]] == cluster_id] <- TRUE\n",
    "    }\n",
    "  }\n",
    "  \n",
    "  # 1. Cluster Map\n",
    "  p1 <- DimPlot(imm, reduction = \"umap\", group.by = res_col, label = TRUE, label.size = 5, repel = TRUE) +\n",
    "    labs(title = sprintf(\"Clusters: %s\", res_col)) + theme_minimal_grid() + theme(legend.position = \"none\")\n",
    "  \n",
    "  # 2. Cell Type Map\n",
    "  p2 <- DimPlot(imm, reduction = \"umap\", group.by = \"major_celltype\", cols = imm_colors) +\n",
    "    labs(title = \"Cell Types (Mapped)\") + theme_minimal_grid() + \n",
    "    theme(legend.position = \"bottom\", legend.text = element_text(size = 6))\n",
    "  \n",
    "  # 3. Impurity Overlay\n",
    "  umap_coords <- imm@reductions$umap@cell.embeddings\n",
    "  colnames(umap_coords) <- c(\"umap_1\", \"umap_2\")\n",
    "  p3 <- ggplot(data.frame(umap_coords, impure = imm@meta.data$impure), \n",
    "               aes(x=umap_1, y=umap_2, color=impure)) +\n",
    "    geom_point(size = 2, alpha = 0.7) +\n",
    "    scale_color_manual(values = c(\"FALSE\" = \"grey80\", \"TRUE\" = \"red\")) +\n",
    "    labs(title = \"Cluster Impurity\", subtitle = \"Red = <90% purity\") +\n",
    "    theme_minimal() + theme(legend.position = \"none\")\n",
    "  \n",
    "  # 4. Bar Composition\n",
    "  ct_tab <- table(imm@meta.data[[res_col]], imm@meta.data$major_celltype)\n",
    "  ct_norm <- as.data.frame(sweep(ct_tab, 1, rowSums(ct_tab), \"/\") * 100) %>%\n",
    "    rename(Cluster = Var1, CellType = Var2, Percentage = Freq) %>%\n",
    "    filter(Percentage > 0)\n",
    "  \n",
    "  p4 <- ggplot(ct_norm, aes(x = Cluster, y = Percentage, fill = CellType)) +\n",
    "    geom_bar(stat = \"identity\", width = 0.8) +\n",
    "    scale_fill_manual(values = imm_colors) +\n",
    "    scale_y_continuous(expand = c(0, 0), limits = c(0, 100)) +\n",
    "    theme_minimal() + labs(title = \"Cluster Composition\") +\n",
    "    theme(axis.text.x = element_text(angle = 90, hjust = 1, size = 7))\n",
    "  \n",
    "  combined <- plot_grid(p1, p2, p3, p4, ncol = 2, nrow = 2)\n",
    "  \n",
    "  # Save output\n",
    "  fname <- file.path(plot_dir, sprintf(\"immune_%s.png\", gsub(\"\\\\.\", \"_\", res_col)))\n",
    "  ggsave(fname, plot = combined, width = 40, height = 30, units = \"cm\", dpi = 300, bg = \"white\")\n",
    "  \n",
    "  # Save CSV summary\n",
    "  summary_df <- data.frame(\n",
    "    Cluster = names(dominant_info),\n",
    "    Dominant = sapply(dominant_info, function(x) x$dominant),\n",
    "    Purity = round(sapply(dominant_info, function(x) x$purity), 2),\n",
    "    N_Cells = sapply(dominant_info, function(x) x$n_cells),\n",
    "    Impure = sapply(dominant_info, function(x) x$purity < 90)\n",
    "  )\n",
    "  write.csv(summary_df, sprintf(\"immune_dominant_%s.csv\", gsub(\"\\\\.\", \"_\", res_col)), row.names = FALSE)\n",
    "}\n",
    "\n",
    "# Final Stats\n",
    "ct_summary <- imm@meta.data %>% group_by(major_celltype) %>% \n",
    "  summarise(n = n(), pct = n()/nrow(.)*100) %>% arrange(desc(n))\n",
    "write.csv(ct_summary, \"immune_celltype_distribution.csv\", row.names = FALSE)\n",
    "print(head(ct_summary))"
   ]
  },
