   "source": [
    "# Epithelial lineage processing\n",
    "\n",
    "library(Seurat)\n",
    "library(qs)\n",
    "library(ggplot2)\n",
    "library(cowplot)\n",
    "library(dplyr)\n",
    "library(gridExtra)\n",
    "\n",
    "# -- Config --\n",
    "lineage <- \"epithelial\"\n",
    "base_path <- \"/kaggle/input/robust-bischoff-2-1-1-subcluster-upload-gd/kaggle stage/\"\n",
    "file_path <- paste0(base_path, \"bischoff_luad_\", lineage, \".qs\")\n",
    "celltypist_csv <- \"/kaggle/input/robust-bischoff-1-celltypist/celltypist_all_levels_comparison.csv\"\n",
    "n_cores <- parallel::detectCores() - 1\n",
    "\n",
    "message(\"Loading Epithelial object...\")\n",
    "epi <- qs::qread(file_path, nthreads = n_cores)\n",
    "\n",
    "# Load annotations and subset\n",
    "celltypist_df <- read.csv(celltypist_csv, row.names = 1)\n",
    "common <- intersect(rownames(epi@meta.data), rownames(celltypist_df))\n",
    "epi <- subset(epi, cells = common)\n",
    "celltypist_df <- celltypist_df[common, ]\n",
    "\n",
    "# Merge metadata\n",
    "cols_to_add <- c(\"granular_raw\", \"granular_raw_conf\", \"granular_majority\", \n",
    "                 \"major_raw\", \"major_raw_conf\", \"major_majority\")\n",
    "for(col in cols_to_add) epi@meta.data[[col]] <- celltypist_df[[col]]\n",
    "\n",
    "epi_mapping <- list(\n",
    "  \"AT1\"                          = \"AT1 (Alveolar type 1)\",\n",
    "  \"AT2\"                          = \"AT2 (Alveolar type 2)\",\n",
    "  \"AT2 proliferating\"            = \"AT2 (Alveolar type 2)\",\n",
    "  \"AT0\"                          = \"Alveolar/Club-like (Tumor)\",\n",
    "  \"Club (non-nasal)\"             = \"Club\",\n",
    "  \"Club (nasal)\"                 = \"Club\",\n",
    "  \"Multiciliated (non-nasal)\"    = \"Ciliated\",\n",
    "  \"Multiciliated (nasal)\"        = \"Ciliated\",\n",
    "  \"Deuterosomal\"                 = \"Ciliated (precursor)\",\n",
    "  \"Neuroendocrine\"               = \"Neuroendocrine\",\n",
    "  \"Basal resting\"                = \"Basal\",\n",
    "  \"Suprabasal\"                   = \"Basal\",\n",
    "  \"Ionocyte\"                     = \"Ionocyte\",\n",
    "  \"Tuft\"                         = \"Tuft\",\n",
    "  \"Goblet (nasal)\"               = \"Club/Secretory\",\n",
    "  \"Goblet (bronchial)\"           = \"Club/Secretory\",\n",
    "  \"Goblet (subsegmental)\"        = \"Club/Secretory\",\n",
    "  \"pre-TB secretory\"             = \"Club/Secretory\",\n",
    "  \"SMG duct\"                     = \"Submucosal gland\",\n",
    "  \"SMG mucous\"                   = \"Submucosal gland\",\n",
    "  \"SMG serous (bronchial)\"       = \"Submucosal gland\",\n",
    "  \"Hillock-like\"                 = \"Hillock-like\"\n",
    ")\n",
    "\n",
    "# Apply mapping\n",
    "epi@meta.data$granular_celltype <- NA_character_\n",
    "epi@meta.data$is_contaminated <- FALSE\n",
    "\n",
    "for (i in seq_along(epi_mapping)) {\n",
    "  epi@meta.data$granular_celltype[epi@meta.data$granular_raw == names(epi_mapping)[i]] <- epi_mapping[[i]]\n",
    "}\n",
    "\n",
    "# Flag contamination\n",
    "contam_mask <- is.na(epi@meta.data$granular_celltype)\n",
    "epi@meta.data$is_contaminated[contam_mask] <- TRUE\n",
    "epi@meta.data$granular_celltype[contam_mask] <- \"**CONTAMINATION**\"\n",
    "\n",
    "cat(sprintf(\"Contamination rate: %.2f%%\\n\", sum(contam_mask)/ncol(epi)*100))\n",
    "\n",
    "# Get resolutions\n",
    "res_cols <- grep(\"SCT_snn_res\\\\.\", colnames(epi@meta.data), value = TRUE)\n",
    "res_cols <- res_cols[order(as.numeric(gsub(\"SCT_snn_res\\\\.\", \"\", res_cols)))]\n",
    "\n",
    "# Analysis Function\n",
    "analyze_resolution <- function(seurat_obj, res_col) {\n",
    "  clusters <- seurat_obj@meta.data[[res_col]]\n",
    "  lineages <- seurat_obj@meta.data$granular_celltype\n",
    "  \n",
    "  out <- list()\n",
    "  for (cid in sort(unique(as.character(clusters)))) {\n",
    "    sub_lin <- lineages[clusters == cid]\n",
    "    counts <- table(sub_lin)\n",
    "    out[[cid]] <- list(\n",
    "      dominant = names(counts)[which.max(counts)],\n",
    "      purity = (max(counts)/sum(counts))*100,\n",
    "      n_cells = length(sub_lin)\n",
    "    )\n",
    "  }\n",
    "  return(out)\n",
    "}\n",
    "\n",
    "# Plotting\n",
    "plot_dir <- \"epithelial_resolution_plots\"\n",
    "dir.create(plot_dir, showWarnings = FALSE)\n",
    "\n",
    "epi_colors <- c(\n",
    "  \"AT1 (Alveolar type 1)\" = \"#1f77b4\",\n",
    "  \"AT2 (Alveolar type 2)\" = \"#aec7e8\",\n",
    "  \"Alveolar/Club-like (Tumor)\" = \"#ff7f0e\",\n",
    "  \"Club\" = \"#2ca02c\",\n",
    "  \"Ciliated\" = \"#98df8a\",\n",
    "  \"Ciliated (precursor)\" = \"#d62728\",\n",
    "  \"Neuroendocrine\" = \"#9467bd\",\n",
    "  \"Basal\" = \"#8c564b\",\n",
    "  \"Ionocyte\" = \"#e377c2\",\n",
    "  \"Tuft\" = \"#7f7f7f\",\n",
    "  \"Club/Secretory\" = \"#bcbd22\",\n",
    "  \"Submucosal gland\" = \"#17becf\",\n",
    "  \"Hillock-like\" = \"#1f77b4\",\n",
    "  \"**CONTAMINATION**\" = \"#FF0000\"\n",
    ")\n",
    "\n",
    "for (res_col in res_cols) {\n",
    "  info <- analyze_resolution(epi, res_col)\n",
    "  \n",
    "  # Mark impurities\n",
    "  epi@meta.data$impure <- FALSE\n",
    "  for (cid in names(info)) {\n",
    "    if (info[[cid]]$purity < 90) \n",
    "      epi@meta.data$impure[epi@meta.data[[res_col]] == cid] <- TRUE\n",
    "  }\n",
    "  \n",
    "  # Plots\n",
    "  p1 <- DimPlot(epi, reduction=\"umap\", group.by=res_col, label=TRUE, repel=TRUE) + \n",
    "        labs(title=res_col) + theme_void() + theme(legend.position=\"none\")\n",
    "  \n",
    "  p2 <- DimPlot(epi, reduction=\"umap\", group.by=\"granular_celltype\", cols=epi_colors) + \n",
    "        labs(title=\"Cell Type\") + theme_void() + theme(legend.position=\"bottom\")\n",
    "  \n",
    "  p3 <- DimPlot(epi, reduction=\"umap\", group.by=\"impure\", cols=c(\"grey90\", \"red\")) + \n",
    "        labs(title=\"Impurity (<90%)\") + theme_void()\n",
    "  \n",
    "  # Composition Barplot\n",
    "  df_bar <- as.data.frame(table(epi@meta.data[[res_col]], epi@meta.data$granular_celltype))\n",
    "  df_bar <- df_bar %>% group_by(Var1) %>% mutate(Freq = Freq/sum(Freq)*100)\n",
    "  \n",
    "  p4 <- ggplot(df_bar, aes(x=Var1, y=Freq, fill=Var2)) + geom_col() +\n",
    "        scale_fill_manual(values=epi_colors) + theme_minimal() + \n",
    "        theme(legend.position=\"none\", axis.text.x=element_text(angle=90))\n",
    "  \n",
    "  comb <- plot_grid(p1, p2, p3, p4, ncol=2)\n",
    "  ggsave(file.path(plot_dir, paste0(\"epithelial_\", res_col, \".png\")), comb, width=12, height=10)\n",
    "  \n",
    "  # Save CSV\n",
    "  res_df <- do.call(rbind, lapply(info, as.data.frame))\n",
    "  res_df$Cluster <- rownames(res_df)\n",
    "  write.csv(res_df, paste0(\"epithelial_dominant_\", res_col, \".csv\"), row.names=FALSE)\n",
    "}\n",
    "\n",
    "# Summary stats\n",
    "stats <- epi@meta.data %>% count(granular_celltype) %>% mutate(pct = n/sum(n)*100)\n",
    "write.csv(stats, \"epithelial_celltype_distribution.csv\")\n",
    "\n",
    "# Extra plot: Raw granular types\n",
    "p_raw <- DimPlot(epi, reduction=\"umap\", group.by=\"granular_raw\", label=FALSE) + theme_void()\n",
    "ggsave(\"epithelial_umap_granular_raw.png\", p_raw, width=10, height=8)"
   ]
  },
