   "source": [
    "# Stromal lineage processing\n",
    "\n",
    "library(Seurat)\n",
    "library(qs)\n",
    "library(ggplot2)\n",
    "library(cowplot)\n",
    "library(dplyr)\n",
    "library(gridExtra)\n",
    "\n",
    "lineage <- \"stromal\"\n",
    "base_path <- \"/kaggle/input/robust-bischoff-2-1-1-subcluster-upload-gd/kaggle stage/\"\n",
    "file_path <- paste0(base_path, \"bischoff_luad_\", lineage, \".qs\")\n",
    "celltypist_csv <- \"/kaggle/input/robust-bischoff-1-celltypist/celltypist_all_levels_comparison.csv\"\n",
    "n_cores <- parallel::detectCores() - 1\n",
    "\n",
    "message(\"Loading Stromal object...\")\n",
    "str <- qs::qread(file_path, nthreads = n_cores)\n",
    "\n",
    "# Annotations\n",
    "ct_df <- read.csv(celltypist_csv, row.names = 1)\n",
    "common <- intersect(rownames(str@meta.data), rownames(ct_df))\n",
    "str <- subset(str, cells = common)\n",
    "ct_df <- ct_df[common, ]\n",
    "\n",
    "str@meta.data$granular_raw <- ct_df$granular_raw\n",
    "str@meta.data$granular_raw_conf <- ct_df$granular_raw_conf\n",
    "\n",
    "# Mapping Dictionary\n",
    "str_mapping <- list(\n",
    "  \"Myofibroblasts\"               = \"Myofibroblasts (Normal-like or Cancer-assoc.)\",\n",
    "  \"Alveolar fibroblasts\"         = \"Fibroblasts\",\n",
    "  \"Adventitial fibroblasts\"      = \"Fibroblasts\",\n",
    "  \"Peribronchial fibroblasts\"    = \"Fibroblasts\",\n",
    "  \"Subpleural fibroblasts\"       = \"Fibroblasts\",\n",
    "  \"Smooth muscle\"                = \"Smooth muscle\",\n",
    "  \"Smooth muscle FAM83D+\"        = \"Smooth muscle\",\n",
    "  \"SM activated stress response\" = \"Smooth muscle\",\n",
    "  \"Pericytes\"                    = \"Pericytes\",\n",
    "  \"Mesothelium\"                  = \"Mesothelial cells\",\n",
    "  \"EC arterial\"                  = \"Endothelial cells\",\n",
    "  \"EC general capillary\"         = \"Endothelial cells\",\n",
    "  \"EC aerocyte capillary\"        = \"Endothelial cells\",\n",
    "  \"EC venous systemic\"           = \"Endothelial cells\",\n",
    "  \"EC venous pulmonary\"          = \"Endothelial cells\",\n",
    "  \"Lymphatic EC mature\"          = \"Lymphatic Endothelial cells\",\n",
    "  \"Lymphatic EC differentiating\" = \"Lymphatic Endothelial cells\"\n",
    ")\n",
    "\n",
    "# Apply mapping\n",
    "str@meta.data$granular_celltype <- NA_character_\n",
    "str@meta.data$is_contaminated <- FALSE\n",
    "\n",
    "for (i in seq_along(str_mapping)) {\n",
    "  str@meta.data$granular_celltype[str@meta.data$granular_raw == names(str_mapping)[i]] <- str_mapping[[i]]\n",
    "}\n",
    "\n",
    "# Contamination check\n",
    "contam_mask <- is.na(str@meta.data$granular_celltype)\n",
    "str@meta.data$is_contaminated[contam_mask] <- TRUE\n",
    "str@meta.data$granular_celltype[contam_mask] <- \"**CONTAMINATION**\"\n",
    "\n",
    "# Resolutions\n",
    "res_cols <- grep(\"SCT_snn_res\\\\.\", colnames(str@meta.data), value = TRUE)\n",
    "res_cols <- res_cols[order(as.numeric(gsub(\"SCT_snn_res\\\\.\", \"\", res_cols)))]\n",
    "\n",
    "# Analyze\n",
    "analyze_resolution <- function(obj, res) {\n",
    "  cl <- obj@meta.data[[res]]\n",
    "  lin <- obj@meta.data$granular_celltype\n",
    "  out <- list()\n",
    "  for (c in unique(cl)) {\n",
    "    sub <- lin[cl == c]\n",
    "    tbl <- table(sub)\n",
    "    out[[as.character(c)]] <- list(\n",
    "      dominant = names(tbl)[which.max(tbl)],\n",
    "      purity = max(tbl)/sum(tbl)*100,\n",
    "      n = length(sub)\n",
    "    )\n",
    "  }\n",
    "  return(out)\n",
    "}\n",
    "\n",
    "# Plotting loop\n",
    "plot_dir <- \"stromal_resolution_plots\"\n",
    "dir.create(plot_dir, showWarnings = FALSE)\n",
    "\n",
    "str_colors <- c(\n",
    "  \"Fibroblasts\" = \"#1b9e77\",\n",
    "  \"Myofibroblasts (Normal-like or Cancer-assoc.)\" = \"#d95f02\",\n",
    "  \"Smooth muscle\" = \"#7570b3\",\n",
    "  \"Pericytes\" = \"#e7298a\",\n",
    "  \"Mesothelial cells\" = \"#66a61e\",\n",
    "  \"Endothelial cells\" = \"#e6ab02\",\n",
    "  \"Lymphatic Endothelial cells\" = \"#a6761d\",\n",
    "  \"**CONTAMINATION**\" = \"#FF0000\"\n",
    ")\n",
    "\n",
    "for (res in res_cols) {\n",
    "  dat <- analyze_resolution(str, res)\n",
    "  \n",
    "  # Impurity flag\n",
    "  str@meta.data$impure <- FALSE\n",
    "  for (c in names(dat)) {\n",
    "    if(dat[[c]]$purity < 90) str@meta.data$impure[str@meta.data[[res]] == c] <- TRUE\n",
    "  }\n",
    "  \n",
    "  # Plot components\n",
    "  p1 <- DimPlot(str, reduction=\"umap\", group.by=res, label=T) + theme_void() + theme(legend.position=\"none\")\n",
    "  p2 <- DimPlot(str, reduction=\"umap\", group.by=\"granular_celltype\", cols=str_colors) + theme_void()\n",
    "  \n",
    "  # Save\n",
    "  comb <- plot_grid(p1, p2, ncol=2)\n",
    "  ggsave(file.path(plot_dir, paste0(\"stromal_\", res, \".png\")), comb, width=12, height=6)\n",
    "  \n",
    "  # Save CSV data\n",
    "  summary_df <- do.call(rbind, lapply(dat, as.data.frame))\n",
    "  write.csv(summary_df, paste0(\"stromal_dominant_\", res, \".csv\"))\n",
    "}\n",
    "\n",
    "# Distribution\n",
    "stats <- str@meta.data %>% group_by(granular_celltype) %>% summarise(n=n()) %>% mutate(pct=n/sum(n))\n",
    "write.csv(stats, \"stromal_celltype_distribution.csv\")\n",
    "message(\"Stromal analysis complete.\")"
   ]
  },
